import pytest
from parse_kv import parse_kv

def test_empty_string():
    """Test with an empty string input."""
    assert parse_kv("") == {}

def test_simple_key_values():
    """Test with simple, well-formed key=value pairs."""
    input_str = "key1=value1; key2=value2; key3=value3"
    expected = {"key1": "value1", "key2": "value2", "key3": "value3"}
    assert parse_kv(input_str) == expected

def test_whitespace_trimming():
    """Test that keys and values are correctly trimmed."""
    input_str = " key1 =  value1 with spaces ; key2=value2 "
    expected = {"key1": "value1 with spaces", "key2": "value2"}
    assert parse_kv(input_str) == expected

def test_complex_values():
    """Test values containing various characters including spaces and '='."""
    input_str = "key_a=value_a; key_b=val=ue_b; key_c=val_with_space "
    expected = {"key_a": "value_a", "key_b": "val=ue_b", "key_c": "val_with_space"}
    assert parse_kv(input_str) == expected

def test_escaped_semicolon():
    """Test that a backslash-escaped semicolon \; is treated as a literal semicolon."""
    input_str = "key1=value1\;with\;semi; key2=value2"
    expected = {"key1": "value1;with;semi", "key2": "value2"}
    assert parse_kv(input_str) == expected

def test_mixed_escaped_and_regular_semicolons():
    """Test mixed usage of escaped and unescaped semicolons."""
    input_str = "k1=val1; k2=val2\;with; k3=val3_only"
    expected = {"k1": "val1", "k2": "val2;with", "k3": "val3_only"}
    assert parse_kv(input_str) == expected

def test_no_equals_sign():
    """Test entries that do not contain an equals sign (should be ignored)."""
    input_str = "key1=value1; justakey; key2=value2; anotherentry"
    expected = {"key1": "value1", "key2": "value2"}
    assert parse_kv(input_str) == expected

def test_only_keys_no_values():
    """Test entries that have an equals sign but no value."""
    input_str = "key1=; key2=value2"
    expected = {"key1": "", "key2": "value2"}
    assert parse_kv(input_str) == expected

def test_only_semicolons():
    """Test string consisting only of separators or whitespace."""
    assert parse_kv(";;; ") == {}
    assert parse_kv(" ") == {}

def test_complex_scenarios():
    """Test a complex scenario mixing all rules."""
    input_str = "  k1 = v1; k2 = v2\\;with\\;semi; k3= ; k4=v4 "
    expected = {"k1": "v1", "k2": "v2;with;semi", "k3": "", "k4": "v4"}
    assert parse_kv(input_str) == expected

